using System;
using System.Collections.Generic;
using UnityEngine;
using B = TooLateToPanic.PanicHomeArt.Builder;
using M = TooLateToPanic.PanicHomeArt.M;

namespace TooLateToPanic
{
    /// <summary>Five original storage assets. Front -Z; visible stock is generated by real LootSources only.</summary>
    public static class PanicV5FurnitureArt
    {
        public static readonly string[] Ids = { "v5_shelf_large", "v5_shelf_small", "v5_cabinet_pantry", "v5_cabinet_wardrobe", "v5_cabinet_utility" };
        static Vector3 V(float x,float y,float z) { return new Vector3(x,y,z); }
        static GameObject Group(GameObject root,string name,Vector3 p)
        { var g=new GameObject(name);g.transform.SetParent(root.transform,false);g.transform.localPosition=p;return g; }
        public static Vector3 Size(string id)
        {
            switch(id)
            {
                case "v5_shelf_large":return V(1.84f,2.12f,.50f);
                case "v5_shelf_small":return V(1.04f,1.12f,.42f);
                case "v5_cabinet_pantry":return V(1.14f,1.96f,.55f);
                case "v5_cabinet_wardrobe":return V(1.62f,2.20f,.64f);
                case "v5_cabinet_utility":return V(1.12f,1.08f,.52f);
                default:throw new ArgumentException("Unknown V5 storage art id: "+id);
            }
        }
        public static GameObject Create(string id,bool colliders=true)
        {
            PanicHomeArt.EnsurePalette();var size=Size(id);var root=new GameObject("V5 "+id);
            var owner=root.AddComponent<PanicV5AssetOwner>();var rig=root.AddComponent<PanicV5FurnitureRig>();
            rig.ArtId=id;rig.LocalSize=size;
            if(id=="v5_shelf_large"||id=="v5_shelf_small")BuildShelf(root,rig,colliders);
            else BuildCabinet(root,rig,colliders);
            Refinish(root,owner);owner.CaptureGeneratedMeshes();return root;
        }
        static void Solid(GameObject root,B b,string name,Vector3 p,Vector3 s,M material,bool collision,float bevel=.01f)
        {
            b.Box(p,s,material,bevel);
            if(collision) {var c=Group(root,"V5 "+name+" collider",p).AddComponent<BoxCollider>();c.size=s;}
        }
        static void Anchor(GameObject root,List<Transform> list,Vector3 p,int index)
        { list.Add(Group(root,"V5 real loot anchor "+index,p).transform); }
        static void BuildShelf(GameObject root,PanicV5FurnitureRig rig,bool collision)
        {
            bool large=rig.ArtId=="v5_shelf_large";Vector3 size=rig.LocalSize;float w=size.x,h=size.y,d=size.z;
            var b=new B();var anchors=new List<Transform>();
            foreach(int side in new[]{-1,1})foreach(int depth in new[]{-1,1})
            {
                Vector3 p=V(side*(w*.5f-.045f),h*.5f,depth*(d*.5f-.045f));
                Solid(root,b,"shelf corner post",p,V(.065f,h,.065f),large?M.Charcoal:M.Walnut,collision,.007f);
                b.Box(V(p.x,.027f,p.z),V(.095f,.054f,.095f),M.Black,.01f);
                for(int n=0;n<(large?9:4);n++)b.Box(V(p.x,.22f+n*.20f,-d*.5f+.006f),V(.015f,.013f,.008f),M.Steel,.002f);
            }
            float[] heights=large?new[]{.34f,.86f,1.38f,1.90f}:new[]{.30f,.80f};
            for(int i=0;i<heights.Length;i++)
            {
                float y=heights[i];
                Solid(root,b,"shelf board",V(0,y,0),V(w-.06f,.065f,d-.035f),M.WalnutLight,collision,.012f);
                b.Box(V(0,y-.042f,-d*.5f+.025f),V(w-.08f,.035f,.035f),large?M.Charcoal:M.WalnutDark,.004f);
                // Edge grain/two dowels read as a crafted object; no decorative fake loot boxes.
                for(int grain=0;grain<3;grain++)b.Box(V(0,y+.033f,-d*.31f+grain*d*.30f),V(w-.12f,.0015f,.004f),M.Walnut,.001f);
                foreach(int side in new[]{-1,1})b.Cylinder(V(side*(w*.5f-.07f),y,-d*.5f+.009f),.012f,.009f,M.Steel,8,Quaternion.Euler(90,0,0));
                Anchor(root,anchors,V(0,y+.04f,large?-.08f:-.06f),i);
            }
            if(large)
            {
                // Cross bracing is behind the usable shelves; never spans the front access volume.
                b.Beam(V(-w*.45f,.15f,d*.46f),V(w*.45f,h-.12f,d*.46f),.023f,M.Steel,.003f);
                b.Beam(V(w*.45f,.15f,d*.46f),V(-w*.45f,h-.12f,d*.46f),.023f,M.Steel,.003f);
                b.Box(V(0,h-.055f,d*.43f),V(w+.015f,.065f,.055f),M.Walnut,.009f);
            }
            else
            {
                foreach(int s in new[]{-1,1})
                {
                    Solid(root,b,"small shelf side panel",V(s*(w*.5f-.035f),.56f,.015f),V(.055f,.94f,d-.04f),M.Walnut,collision,.012f);
                    b.Box(V(s*(w*.5f-.005f),.76f,-d*.5f-.007f),V(.045f,.085f,.012f),M.Steel,.005f);
                }
                b.Box(V(0,h-.04f,0),V(w,.08f,d),M.WalnutLight,.018f);
                Solid(root,b,"small shelf back",V(0,.58f,d*.5f-.023f),V(w-.08f,.91f,.034f),M.Linen,collision,.005f);
            }
            b.Attach(root,"ShelfJoineryBracingGrainFeet");rig.LootAnchors=anchors.ToArray();
        }
        static void BuildCabinet(GameObject root,PanicV5FurnitureRig rig,bool collision)
        {
            bool pantry=rig.ArtId=="v5_cabinet_pantry",wardrobe=rig.ArtId=="v5_cabinet_wardrobe";
            Vector3 size=rig.LocalSize;float w=size.x,h=size.y,d=size.z;
            M body=pantry?M.Linen:wardrobe?M.Slate:M.Olive;
            var b=new B();var doors=new List<Transform>();var degrees=new List<float>();var anchors=new List<Transform>();
            foreach(int sx in new[]{-1,1})foreach(int sz in new[]{-1,1})
                Solid(root,b,"cabinet foot",V(sx*(w*.5f-.095f),.075f,sz*(d*.5f-.075f)),V(.11f,.15f,.10f),M.WalnutDark,collision,.014f);
            Solid(root,b,"cabinet left wall",V(-w*.5f+.032f,h*.5f+.055f,0),V(.065f,h-.11f,d),body,collision,.012f);
            Solid(root,b,"cabinet right wall",V(w*.5f-.032f,h*.5f+.055f,0),V(.065f,h-.11f,d),body,collision,.012f);
            Solid(root,b,"cabinet back",V(0,h*.5f+.05f,d*.5f-.025f),V(w-.065f,h-.15f,.045f),M.Walnut,collision,.005f);
            Solid(root,b,"cabinet bottom",V(0,.18f,0),V(w-.05f,.065f,d),body,collision,.01f);
            Solid(root,b,"cabinet top",V(0,h-.045f,0),V(w+.015f,.09f,d+.025f),body,collision,.015f);
            float[] levels=wardrobe?new[]{.34f,1.04f,1.72f}:pantry?new[]{.38f,.88f,1.38f}:new[]{.31f,.73f};
            for(int i=0;i<levels.Length;i++)
            {
                float y=levels[i];Solid(root,b,"cabinet interior shelf",V(0,y,.01f),V(w-.13f,.045f,d-.075f),M.WalnutLight,collision,.008f);
                Anchor(root,anchors,V(0,y+.04f,wardrobe?-.05f:pantry?-.04f:-.05f),i);
            }
            if(wardrobe)
            {
                b.Cylinder(V(0,1.60f,.04f),.016f,w-.17f,M.Steel,10,Quaternion.Euler(0,0,90));
                b.Box(V(0,h-.12f,-d*.5f-.015f),V(w+.045f,.07f,.065f),M.WalnutLight,.012f);
            }
            if(pantry||wardrobe)
            {
                foreach(int s in new[]{-1,1})
                {
                    float doorWidth=w*.5f-.045f,doorHeight=h-.28f;
                    var hinge=Group(root,"V5 cupboard hinge "+s,V(s*(w*.5f-.04f),(h+.16f)*.5f,-d*.5f-.012f));var db=new B();
                    float cx=-s*doorWidth*.5f;
                    Solid(hinge,db,"opening door",V(cx,0,0),V(doorWidth,doorHeight,.052f),body,collision,.015f);
                    if(pantry)
                    {
                        for(int slat=0;slat<13;slat++)db.Box(V(cx,-doorHeight*.40f+slat*(doorHeight*.80f/12),-.033f),V(doorWidth-.10f,.045f,.023f),M.WalnutLight,.005f,Quaternion.Euler(10,0,0));
                    }
                    else
                    {
                        db.Box(V(cx,0,-.038f),V(doorWidth-.14f,doorHeight-.17f,.026f),M.WalnutDark,.022f);
                        for(int strip=0;strip<4;strip++)db.Box(V(cx+(strip-1.5f)*.13f,0,-.055f),V(.008f,doorHeight-.24f,.008f),M.Slate,.002f);
                    }
                    db.Beam(V(-s*(doorWidth-.07f),-.12f,-.07f),V(-s*(doorWidth-.07f),.12f,-.07f),.027f,M.Steel);
                    foreach(float y in new[]{-doorHeight*.35f,doorHeight*.35f})db.Box(V(0,y,-.025f),V(.035f,.075f,.06f),M.Steel,.005f);
                    db.Attach(hinge,"LouveredOrInsetOpeningDoorHardware");doors.Add(hinge.transform);degrees.Add(-s*98f);
                }
            }
            else
            {
                // A visible asymmetric utility unit: left cupboard, right three actual drawer fronts.
                float leftWidth=w*.51f;
                var hinge=Group(root,"V5 utility cupboard hinge",V(-w*.5f+.04f,.59f,-d*.5f-.015f));var db=new B();
                Solid(hinge,db,"utility opening door",V(leftWidth*.5f,0,0),V(leftWidth,.75f,.052f),body,collision,.012f);
                db.Box(V(leftWidth*.78f,0,-.045f),V(.11f,.032f,.025f),M.Steel,.006f);
                db.Box(V(leftWidth*.50f,0,-.031f),V(leftWidth-.11f,.60f,.012f),M.WalnutLight,.012f);
                db.Attach(hinge,"UtilitySingleDoor");doors.Add(hinge.transform);degrees.Add(97f);
                for(int drawer=0;drawer<3;drawer++)
                {
                    float y=.34f+drawer*.26f;
                    b.Box(V(w*.26f,y,-d*.5f-.018f),V(w*.43f,.23f,.06f),body,.012f);
                    b.Beam(V(w*.26f-.10f,y,-d*.5f-.063f),V(w*.26f+.10f,y,-d*.5f-.063f),.023f,M.Steel,.004f);
                }
                b.Box(V(0,h+.002f,0),V(w+.055f,.055f,d+.055f),M.WalnutLight,.012f);
            }
            b.Attach(root,"CabinetCarcassShelvesFeetCornice");rig.Doors=doors.ToArray();rig.OpenAngles=degrees.ToArray();rig.LootAnchors=anchors.ToArray();
        }
        static void Refinish(GameObject root,PanicV5AssetOwner owner)
        {
            var map=new Dictionary<Material,Material>();
            foreach(var r in root.GetComponentsInChildren<Renderer>(true))
            {
                var materials=r.sharedMaterials;
                for(int i=0;i<materials.Length;i++)
                {
                    var source=materials[i];if(!source)continue;
                    if(!map.TryGetValue(source,out var mat))
                    {
                        mat=new Material(source){name="V5 storage "+source.name};mat.SetFloat("_Glossiness",.20f);
                        if(source.name.EndsWith("Slate"))mat.color=new Color(.18f,.28f,.42f);
                        if(source.name.EndsWith("Olive"))mat.color=new Color(.37f,.48f,.37f);
                        if(source.name.EndsWith("Linen"))mat.color=new Color(.84f,.81f,.69f);
                        if(source.name.EndsWith("Steel")){mat.SetFloat("_Metallic",.55f);mat.SetFloat("_Glossiness",.42f);}
                        map[source]=mat;owner.Owned.Add(mat);
                    }
                    materials[i]=mat;
                }
                r.sharedMaterials=materials;
            }
        }
    }
}
